use corpse_core::{startup,storage,non_euclidean_generation as ne,pocket_biomes,portals_generation as pg};
use serde_json::json;
use std::{collections::HashSet,sync::{Arc,atomic::{AtomicUsize,Ordering}},time::Instant};
fn seed(i:usize)->String {match i%8 {0=>format!("r37-event-count-{:04}",i/8),1=>format!("r38-stress-{}",i/8),2=>format!("{}",i/8),3=>format!("0-1-2:qa-{}",i/8),4=>format!("11-10-9:qa-{}",i/8),5=>format!("生成-é-🌱-{}",i/8),6=>format!("{}-{}", "x".repeat(256),i/8),_=>format!("qa-mixed-{:016x}",(i as u64).wrapping_mul(0x9e3779b97f4a7c15))}}
fn check(r:&corpse_core::Run)->Vec<String>{let mut errors=vec![];if r.floors.len()!=40 {errors.push(format!("floor_count:{}",r.floors.len()));}if let Err(e)=storage::validate(r){errors.push(format!("storage:{e}"));}if let Err(e)=storage::validate_current_revision(r){errors.push(format!("admission:{e}"));}
let plan=corpse_core::generation::domain_plan_revision(corpse_core::rng::seed_hash(&r.seed),r.simulation_revision.value_or(29.));for f in &r.floors {let d=f.depth;let expected=&plan[(d as usize-1)/5];if f.domain!=expected.domain{errors.push(format!("domain-changed:{d}"));}if expected.godbeast_depth==d as i32&&f.godbeast_event.as_ref().map(|e|e.kind.as_str())!=Some(expected.godbeast_kind.as_str()){errors.push(format!("required-godbeast:{d}:{}",expected.godbeast_kind));}let w=f.width();if let Some(details)=f.generation.as_ref().and_then(|g|g.stages.iter().find(|s|s.id=="cleanup")).and_then(|s|s.details.as_ref()){if details.get("qualityAccepted")!=Some(&1.){errors.push(format!("quality-not-accepted:{d}"));}if details.get("generationAttempt").is_some_and(|v|*v>=256.){errors.push(format!("generation-bound:{d}"));}}let reach=corpse_core::generation::reachable_without_braziers(f,None);if !corpse_core::generation::transitions_accessible(f,&reach){errors.push(format!("stairs-unreachable:{d}"));}let ground=r.ground.get(&(d as u32).to_string()).map(|v|v.as_slice()).unwrap_or(&[]);let mut occupied=HashSet::new();if !ne::traversable(f){errors.push(format!("routes:{d}"));}if !pocket_biomes::validate(f){errors.push(format!("biomes:{d}"));}if !pg::all_endpoints_optional(f){errors.push(format!("portal-route:{d}"));}
for g in ground {let at=g.y as usize*w+g.x as usize;if at>=f.tiles.len()||!matches!(f.tiles[at].as_str(),"floor"|"grass"|"shallow-water"|"water"){errors.push(format!("ground-terrain:{d}:{}:{},{}:{}",g.item.name,g.x,g.y,f.tiles.get(at).map_or("OOB",|s|s.as_str())));}if !occupied.insert((g.x as i32,g.y as i32)){errors.push(format!("ground-overlap:{d}:{},{}",g.x,g.y));}}
let item_cells=occupied;let mut occupied=HashSet::new();for a in r.actors_at(d){if item_cells.contains(&(a.x as i32,a.y as i32)){errors.push(format!("actor-item-overlap:{d}:{}:{},{}",a.name,a.x,a.y));}let at=a.y as usize*w+a.x as usize;if at>=f.tiles.len()||matches!(f.tiles[at].as_str(),"wall"|"tree"|"chasm"|"up"|"down"){errors.push(format!("actor-terrain:{d}:{}:{},{}:{}",a.name,a.x,a.y,f.tiles.get(at).map_or("OOB",|s|s.as_str())));}if !occupied.insert((a.x as i32,a.y as i32)){errors.push(format!("actor-overlap:{d}:{}:{},{}",a.name,a.x,a.y));}}
if let Some(e)=f.godbeast_event.as_ref(){if e.kind=="Veridian" {let taps:Vec<_>=ground.iter().filter(|g|g.item.effect.as_ref().is_some_and(|e|e=="tree-tap")).collect();if taps.len()!=1{errors.push(format!("required-tap:{d}:{}",taps.len()));}else if let Some(t)=e.tap.as_ref(){if taps[0].x!=t.x||taps[0].y!=t.y{errors.push(format!("tap-location:{d}"));}}}if e.kind=="Zillennia" && !r.actors_at(d).iter().any(|a|a.zillennia_quality.as_ref().is_some()){errors.push(format!("zillennia-missing:{d}"));}}
if let Some(s)=f.sphinx_room.as_ref(){for at in &s.reward_cells {if !ground.iter().any(|g|g.y as usize*w+g.x as usize==*at as usize){errors.push(format!("sphinx-reward:{d}:{at}"));}}}
if let Some(at)=corpse_core::phantasmii_generation::dagger_cell(f){let shards=ground.iter().filter(|g|g.item.name=="Shards of the Phantasmii").count();if shards!=3{errors.push(format!("shard-count:{d}:{shards}"));}if !ground.iter().any(|g|g.y as usize*w+g.x as usize==at&&corpse_core::phantasmii_generation::is_dagger(&g.item)){errors.push(format!("dagger-missing:{d}"));}}
}errors}
fn main(){let args:Vec<_>=std::env::args().collect();let n:usize=args.get(1).map_or(1024,|x|x.parse().unwrap());let rev:f64=args.get(2).map_or(38.,|x|x.parse().unwrap());let threads:usize=args.get(3).map_or(4,|x|x.parse().unwrap());let next=Arc::new(AtomicUsize::new(0));let start=Instant::now();let mut handles=vec![];for _ in 0..threads {let next=next.clone();handles.push(std::thread::spawn(move||loop{let i=next.fetch_add(1,Ordering::Relaxed);if i>=n{break}let seed=seed(i);let t=Instant::now();let result=std::panic::catch_unwind(||{let mut r=startup::new_run_shell_revision(&seed,"Unblessed",false,rev)?;startup::ensure_floors(&mut r,40)?;let mut errors=check(&r);let mut repeated=false;let mut loaded=false;if i%67==0 {let mut repeat=startup::new_run_shell_revision(&seed,"Unblessed",false,rev)?;startup::ensure_floors(&mut repeat,40)?;if r!=repeat{errors.push("determinism".into());}repeated=true;match storage::deserialize(&storage::serialize(&r).map_err(|e|e.to_string())?){Ok(s)=>{if !storage::canonical_equal(&serde_json::to_value(&r).unwrap(),&serde_json::to_value(&s).unwrap()){errors.push("roundtrip".into());}loaded=true;},Err(e)=>errors.push(format!("load:{e}"))}}Ok::<_,String>(json!({"index":i,"seed":seed,"normalized_seed":r.seed,"revision":rev,"floors":r.floors.len(),"population_retries":r.floors.iter().filter_map(|f|f.generation.as_ref().and_then(|g|g.stages.iter().find(|s|s.id=="cleanup")).and_then(|s|s.details.as_ref()).and_then(|d|d.get("populationAttempt"))).filter(|v|**v>0.).count(),"errors":errors,"repeated":repeated,"loaded":loaded,"elapsed_ms":t.elapsed().as_millis()}))});match result{Ok(Ok(row))=>println!("{row}"),Ok(Err(e))=>println!("{}",json!({"index":i,"seed":seed,"generation_error":e})),Err(_)=>println!("{}",json!({"index":i,"seed":seed,"panic":true}))}}));}for h in handles{h.join().unwrap()}eprintln!("TOTAL attempted={n} elapsed_ms={}",start.elapsed().as_millis());}
